commits.patch:
diff --git a/src/type1/t1parse.c b/src/type1/t1parse.c
index 6947b3d..6690605 100644
--- a/src/type1/t1parse.c
+++ b/src/type1/t1parse.c
@@ -281,11 +281,20 @@
         if ( error )
           goto Fail;

-        if ( tag != 0x8002U )
+        if ( tag != 0x8002U || size > stream->size - stream->pos )
           break;

-        if ( FT_QREALLOC( priv_dict, priv_len, priv_len + size ) ||
-             FT_STREAM_READ( priv_dict + priv_len, size )        )
+        if ( FT_QREALLOC( priv_dict, priv_len, priv_len + size ) )
+          goto Fail;
+
+        if ( !stream->read )
+        {
+          FT_MEM_COPY( priv_dict + priv_len, stream->base + stream->pos,
+                       size );
+          if ( FT_STREAM_SKIP( size ) )
+            goto Fail;
+        }
+        else if ( FT_STREAM_READ( priv_dict + priv_len, size ) )
           goto Fail;

         priv_len += size;
